{
  "envelope": {
    "subject": {
      "use": "notUsed",
      "forms": [],
      "description": "The Data Exchange message is identified by its message type; it has no subject record."
    },
    "dataRequired": true,
    "version": "1.0",
    "contentType": "text/json",
    "messageType": "DataExchange.Definition.Import"
  },
  "parameters": [
    {
      "name": "storageCode",
      "type": "string",
      "required": false,
      "description": "The storage connection of the file. Required with path unless contentBase64 is sent. Resolve it with Storage.Account.List."
    },
    {
      "name": "path",
      "type": "string",
      "required": false,
      "description": "The file path in storage. Required with storageCode unless contentBase64 is sent. The file is read and stays unchanged."
    },
    {
      "name": "contentBase64",
      "type": "string",
      "required": false,
      "description": "The file content encoded as base64, at most 1 MB. Send instead of storageCode and path."
    },
    {
      "name": "uploadId",
      "type": "string",
      "required": false,
      "description": "The uploadId of a complete chunked upload that holds the XML. The upload is consumed."
    },
    {
      "name": "overwrite",
      "type": "boolean",
      "required": false,
      "description": "When true, an existing definition with the same code is deleted and installed again. Default false.",
      "default": false
    },
    {
      "name": "newCode",
      "type": "string",
      "required": false,
      "description": "Optional code to install a file with one definition under, for example to copy a definition."
    }
  ],
  "response": {
    "contentType": "text/json",
    "description": "Every success answers status Success. The fields below belong to the data object, not to the top level.",
    "status": "Success",
    "payloadPath": "data",
    "fields": [
      {
        "name": "codes",
        "type": "array",
        "description": "The installed definition codes."
      },
      {
        "name": "lineDefs",
        "type": "integer",
        "description": "Number of line definitions installed."
      },
      {
        "name": "mappings",
        "type": "integer",
        "description": "Number of mappings installed."
      },
      {
        "name": "overwritten",
        "type": "array",
        "description": "Codes of existing definitions that were replaced."
      }
    ]
  },
  "errors": [
    {
      "code": "RecordNotFound",
      "when": "A missing storage file or folder returns RecordNotFound on path or sourcePath, using the path exactly as sent without account, container or base-path details.",
      "fix": "Use Storage.File.List or Storage.File.Exists to check the path, then retry."
    },
    {
      "code": "MissingParameter",
      "when": "A required request parameter is missing.",
      "fix": "Provide the named parameter and retry."
    },
    {
      "code": "InvalidParameterFormat",
      "when": "The file cannot be read in the definition file type. The refusal identifies contentBase64, path or uploadId and reports only the file name or size, never its content.",
      "fix": "Supply the required XML, CSV or fixed width file and retry. Inspect the definition with DataExchange.Definition.Get; use DataExchange.Definition.Export for the definition XML format."
    },
    {
      "code": "InvalidParameter",
      "when": "A parameter is outside the allowed values or length.",
      "fix": "Correct every reported parameter using expected and nextStep, then retry."
    },
    {
      "code": "MultipleErrors",
      "when": "Several parameters are invalid; errors lists every problem.",
      "fix": "Correct every reported parameter using expected and nextStep, then retry."
    },
    {
      "code": "RecordNotFound",
      "when": "The supplied definition code does not exist.",
      "fix": "Choose an existing compatible definition using DataExchange.Definition.List."
    },
    {
      "code": "PreconditionFailed",
      "when": "The definition is referenced or incompatible with this operation.",
      "fix": "Choose an existing compatible definition using DataExchange.Definition.List."
    },
    {
      "code": "LimitExceeded",
      "when": "Inline content or an inline file is larger than 1 MB.",
      "fix": "Use storageCode with path, or a chunked upload."
    },
    {
      "code": "RecordNotFound",
      "when": "The storageCode does not name a storage connection.",
      "fix": "Use Storage.Account.List to find the storageCode."
    },
    {
      "code": "PreconditionFailed",
      "when": "The storage connection is disabled.",
      "fix": "Enable it on the Bifrost Storage Connection card, or use another storageCode."
    },
    {
      "code": "RecordNotFound",
      "when": "No upload session exists for the uploadId, or the session was begun by another user.",
      "fix": "Send the uploadId that Storage.Upload.Begin returned, as the user who began the session, or begin a new session."
    },
    {
      "code": "PreconditionFailed",
      "when": "The upload session is no longer open (already committed or aborted).",
      "fix": "Begin a new session and send the file again."
    },
    {
      "code": "PreconditionFailed",
      "when": "The session has no chunks, its sequence numbers are not contiguous, or the received size differs from declaredSize.",
      "fix": "Call Storage.Upload.Status, append the missing or wrong chunks, then commit again."
    },
    {
      "code": "BusinessCentralError",
      "when": "Other storage provider failures return BusinessCentralError with localized text and no provider URL.",
      "fix": "Check the storage connection and provider permissions, then retry."
    }
  ],
  "effect": {
    "effect": "write",
    "changes": "Writes Data Exchange definitions, types, entries and parsed fields, and the business records of processed mappings, within the transaction of the call. A file written to storage is the last step; a later failure rolls the call back. With process true the import is committed before the mappings run.",
    "idempotent": false,
    "permissionSet": "BIFROST DataExch ori",
    "preconditions": "The caller holds BIFROST DataExch ori and the Business Central permissions of the tables the operation writes; supplied definitions and entries must exist and support the operation. A storageCode must name an enabled storage connection."
  },
  "metering": {
    "chargeable": true,
    "chargedAs": "message"
  },
  "related": [
    {
      "name": "DataExchange.Definition.Export",
      "useInsteadWhen": "Write a definition as XML."
    },
    {
      "name": "DataExchange.Definition.Get",
      "useInsteadWhen": "Read the installed definition."
    },
    {
      "name": "DataExchange.Type.Set",
      "useInsteadWhen": "Wire an import definition to incoming documents."
    }
  ],
  "workflow": {
    "steps": [
      {
        "messageType": "DataExchange.Definition.Export",
        "purpose": "Write an existing definition as XML."
      },
      {
        "messageType": "DataExchange.Definition.Import",
        "purpose": "Install or replace definitions from XML."
      },
      {
        "messageType": "DataExchange.Definition.Get",
        "purpose": "Check the installed definition."
      },
      {
        "messageType": "DataExchange.Definition.Delete",
        "purpose": "Remove a definition that is no longer used."
      }
    ],
    "text": "Export and Import use the same XML format as the Business Central actions of the same name, so a definition can move between environments."
  },
  "examples": [
    {
      "title": "A successful request",
      "request": {
        "type": "DataExchange.Definition.Import",
        "data": {
          "storageCode": "ARCHIVE",
          "path": "definitions/invoices.xml"
        },
        "lcid": 1033
      },
      "response": {
        "status": "Success",
        "data": {
          "codes": [
            "INVOICES"
          ],
          "lineDefs": 1,
          "mappings": 1,
          "overwritten": []
        }
      }
    },
    {
      "title": "A request refused before any change",
      "request": {
        "type": "DataExchange.Definition.Import",
        "data": {
          "contentBase64": "not-base64!"
        },
        "lcid": 1033
      },
      "response": {
        "status": "Error",
        "code": "InvalidParameterFormat",
        "error": "Parameter \"contentBase64\" is not valid base64 content.",
        "parameter": "contentBase64",
        "expected": "base64 content",
        "nextStep": "Encode the file bytes as standard base64 and send them again.",
        "hint": "For usage details, call the \"Help.Implementation.Get\" message type with subject \"DataExchange.Definition.Import\". Always read the help before calling a message type."
      }
    },
    {
      "title": "Refusal: required request data is missing",
      "request": {
        "type": "DataExchange.Definition.Import",
        "data": {},
        "lcid": 1033
      },
      "response": {
        "status": "Error",
        "code": "MultipleErrors",
        "error": "2 problems in the request. Nothing was changed.",
        "errors": [
          {
            "code": "MissingParameter",
            "error": "Parameter \"storageCode\" is required.",
            "parameter": "storageCode",
            "received": "not supplied",
            "expected": "a JSON string of at most 20 characters",
            "nextStep": "Send \"storageCode\" as a JSON string of at most 20 characters and retry."
          },
          {
            "code": "MissingParameter",
            "error": "Parameter \"path\" is required.",
            "parameter": "path",
            "received": "not supplied",
            "expected": "a JSON string of at most 2048 characters",
            "nextStep": "Send \"path\" as a JSON string of at most 2048 characters and retry."
          }
        ],
        "hint": "For usage details, call the \"Help.Implementation.Get\" message type with subject \"DataExchange.Definition.Import\". Always read the help before calling a message type."
      }
    }
  ],
  "overview": "Reads the XML from storageCode and path, from contentBase64 (at most 1 MB) or from a complete chunked upload (uploadId, which is consumed), and installs it with the base XMLport Imp / Exp Data Exch Def & Map. newCode installs a single definition under another code.",
  "notes": "An existing code is refused unless overwrite is true; overwrite deletes the existing definition with its lines and mappings first. Every code in the file is checked before anything is installed. Wire an import definition to incoming documents with DataExchange.Type.Set."
}

## Errors and warnings
An error response has `status` = `Error`, a stable `code`, the `error` text and, when they apply, `parameter` (the request parameter concerned, e.g. `lines[2].no`), `received` (the value received), `expected` (what was expected) and `nextStep` (what to do now). `hint` says where to read more.
When a request has several problems, all of them are listed in `errors[]` - each with the same fields - under a top-level `code` (`MultipleErrors`, or a shared code such as `InvalidLine` for the `lines` of a Create type) and a summary `error`. Fix them all before calling again. One problem is reported at the top level, with no `errors[]`.
Request values are checked first and every problem found is reported together. A Business Central validation error raised afterwards, while a record is being written, stops the call and is reported on its own: `code` = `BusinessCentralError`, Business Central's own `error` text, and `parameter` naming the request parameter being applied, e.g. `lines[1].accountNo`. Nothing is written.
Request values are read in one format, whatever the language: dates `YYYY-MM-DD`; date-times ISO 8601 with `Z` or an offset; amounts as JSON numbers (or a string such as `"1234.56"`, no thousands separator); integers as JSON integers; booleans `true` or `false`. Any other value is `InvalidParameterFormat` with `received` and `expected`; for an unambiguous local form such as `26.09.2026`, `nextStep` gives the value to resend. Every bad value of a request is reported together.
Answers are written in one format as well, whatever the language of the call: dates `YYYY-MM-DD`, date-times ISO 8601, numbers with a dot and no thousands separator, and the option and enum values of every answer except `Data.Records.Get` and `Data.Records.Set` as their English names, so a value read from an answer can be sent back. Those two answer the caption of the language of the call, for a person to read. The language of the call (`lcid`) changes captions and message texts, not these forms. Two things are outside Bifrost's control: Business Central writes its own texts (a ledger entry description such as `Direct Cost V00010 on 10/02/26`, the text of a `BusinessCentralError`) with the regional settings of the server session, which `lcid` does not change, so a date in such a text can be in month-day order; and a table view is read with those settings too, so write dates in a view as `YYYY-MM-DD` and decimals with a dot.
Both success and error responses can carry `warnings[]`, each with `code`, `message` and, when they apply, `parameter` and `nextStep`.
`UnknownParameter` normally warns about undeclared data keys without changing status, validationResult or domain warningCount. Set the root envelope option `strict:true` (next to type and subject, never inside data) to refuse every unknown key before execution. Strict refusals list the keys and localized nextStep corrections; no business changes or successful execution charges occur. With strict omitted or false, warnings join success and error responses as before. Example: {"type":"Memory.User.Set","strict":true,"data":{"memory":"test","memry":"typo"}} is refused.
`FieldChangedByBC` is a warning from Data.Records.Set: another field validation or the write changed a sent field after its own validation. `parameter` names data[n].fields.{jsonName}, counting from 0. Status stays Success. Compare the returned values with what you sent; follow `nextStep` to use validation order or send the field again in a separate call. Normalisation of the field itself, LCY, Dimension Set ID, BLOB, Media, MediaSet and skipped fields are excluded.
Feature apps (Foundation 28.0.8 or later) can call `Argument.SetErrorContext(Parameter, Expected, NextStep)` before an operation that may fail after writes, then `Argument.ClearErrorContext()` after success. Supply the parameter name and translated labels, never request values, file content, credentials or a call stack. Foundation returns that context on the original `BusinessCentralError` after rollback, including uncaught task errors; `RespondWithLastError()` also uses it. The API does not catch errors, commit data or change the transaction boundary. Keep no-return `Codeunit.Run` and let errors propagate for chained `OmitCommit` calls; never add a Boolean `Codeunit.Run` or a writing `TryFunction` to recover context. Context is cleared between messages. Existing callers without context keep their response shape; recognized lock errors keep their existing `Retryable` guidance.
`Retryable` means a transient lock or deadlock caught while writing or posting. `error` keeps Business Central's original text. `expected` is "no concurrent lock on the same records"; `nextStep` is "Retry the same call after a few seconds; nothing was changed." Bifrost does not retry automatically. Other platform errors, including uncaught queue-path errors, remain `BusinessCentralError`.
Codes: `MissingParameter`, `InvalidParameterFormat`, `InvalidParameter`, `RecordNotFound`, `AmbiguousRecord`, `ConflictingIdentifiers`, `InvalidFilterField`, `InvalidLine`, `NothingToPreview`, `LinesSkipped`, `BlockedByWriteGuard`, `PreconditionFailed`, `PermissionDenied`, `LimitExceeded`, `BusinessCentralError`, `MultipleErrors`, `DeprecatedParameter`, `UnknownParameter`, `FieldChangedByBC`, `Retryable`, `EULA_REQUIRED`, `TRIAL_NOT_STARTED`. The `error` text may be translated; the code never is.
